//! Map Amazon Bedrock SDK errors to [`paigasus_helikon_core::ModelError`].
//!
//! Per ADR-10 (*No silent auto-retry inside the loop*), the runner never
//! retries — retries are an application-layer concern via `RetryingModel`.
//!
//! The `classify` function is a pure, unit-testable classifier that operates
//! on string error codes and optional HTTP status codes, mirroring the style
//! of the Anthropic provider's `map_error_type`. `map_sdk_error` wraps it
//! by extracting the code/status from the real [`SdkError`] variants.

use aws_smithy_runtime_api::client::result::SdkError;
use aws_smithy_runtime_api::http::Headers;
use aws_smithy_types::error::metadata::ProvideErrorMetadata;
use paigasus_helikon_core::ModelError;

/// Classify a Bedrock error into a [`ModelError`] from raw components.
///
/// This function is intentionally pure so it can be unit-tested without
/// constructing live `SdkError` values.
///
/// | `code`                       | Result                             |
/// |------------------------------|------------------------------------|
/// | `ThrottlingException`        | `RateLimited { retry_after_ms }`   |
/// | `ServiceUnavailableException`, `ModelNotReadyException`, `InternalServerException`, `ModelStreamErrorException`, `ModelTimeoutException` | `Unavailable` |
/// | `AccessDeniedException`      | `Refused { reason: message }`      |
/// | `ValidationException` + message contains "too long"/"maximum context" | `ContextLengthExceeded` |
/// | `ValidationException` (other)| `Other`                            |
/// | unknown / `None`             | `Other`                            |
pub(crate) fn classify(
    code: Option<&str>,
    _status: Option<u16>,
    message: &str,
    retry_after_ms: Option<u64>,
) -> ModelError {
    match code {
        Some("ThrottlingException") => ModelError::RateLimited { retry_after_ms },
        Some(
            "ServiceUnavailableException"
            | "ModelNotReadyException"
            | "InternalServerException"
            | "ModelStreamErrorException"
            | "ModelTimeoutException",
        ) => ModelError::Unavailable,
        Some("AccessDeniedException") => ModelError::Refused {
            reason: message.to_owned(),
        },
        Some("ValidationException") => {
            let msg_lower = message.to_ascii_lowercase();
            if msg_lower.contains("too long") || msg_lower.contains("maximum context") {
                ModelError::ContextLengthExceeded
            } else {
                ModelError::Other(anyhow::anyhow!("bedrock ValidationException: {message}"))
            }
        }
        _ => ModelError::Other(anyhow::anyhow!(
            "bedrock error {}: {message}",
            code.unwrap_or("unknown")
        )),
    }
}

/// Parse the `Retry-After` header (integer seconds) from Bedrock response headers into milliseconds.
///
/// Returns `None` when the header is absent or its value is not a non-negative integer
/// (HTTP-date retry-after values are not supported — `None` is the safe fallback).
pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
    headers
        .get("retry-after")
        .and_then(|v| v.trim().parse::<u64>().ok())
        .map(|seconds| seconds.saturating_mul(1000))
}

/// Map a Bedrock SDK [`SdkError`] to a [`ModelError`].
///
/// For `ServiceError`, the modeled error code and message are extracted via
/// [`ProvideErrorMetadata`] and delegated to [`classify`]. Transport-level
/// failures (`DispatchFailure`, `TimeoutError`, `ConstructionFailure`,
/// `ResponseError`) map to [`ModelError::Transport`].
///
/// This generic variant does **not** inspect HTTP headers (the response type `R`
/// may not be an HTTP response — e.g. the event-stream `recv()` path produces
/// `SdkError<_, RawMessage>`). Call [`map_sdk_http_error`] when `R` is known to
/// be [`aws_smithy_runtime_api::http::Response`] and you want `Retry-After`
/// header extraction.
pub(crate) fn map_sdk_error<E, R>(err: SdkError<E, R>) -> ModelError
where
    E: ProvideErrorMetadata + std::fmt::Debug,
    R: std::fmt::Debug,
{
    match &err {
        SdkError::ServiceError(svc) => {
            let code = svc.err().code();
            let message = svc.err().message().unwrap_or("");
            classify(code, None, message, None)
        }
        SdkError::DispatchFailure(_)
        | SdkError::TimeoutError(_)
        | SdkError::ConstructionFailure(_)
        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
        // Non-exhaustive: treat any future variant as transport.
        _ => ModelError::Transport(format!("{err:?}")),
    }
}

/// Map a Bedrock SDK [`SdkError`] whose response type is the concrete HTTP
/// response to a [`ModelError`], extracting `Retry-After` header and HTTP
/// status from the raw response.
///
/// This is the preferred variant for the initial `fluent.send()` call on a
/// Bedrock operation, where the SDK returns
/// `SdkError<E, aws_smithy_runtime_api::client::orchestrator::HttpResponse>`.
pub(crate) fn map_sdk_http_error<E>(
    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
) -> ModelError
where
    E: ProvideErrorMetadata + std::fmt::Debug,
{
    match &err {
        SdkError::ServiceError(svc) => {
            let code = svc.err().code();
            let message = svc.err().message().unwrap_or("");
            let raw = svc.raw();
            let status = Some(raw.status().as_u16());
            let retry_after_ms = parse_retry_after_ms(raw.headers());
            classify(code, status, message, retry_after_ms)
        }
        SdkError::DispatchFailure(_)
        | SdkError::TimeoutError(_)
        | SdkError::ConstructionFailure(_)
        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
        // Non-exhaustive: treat any future variant as transport.
        _ => ModelError::Transport(format!("{err:?}")),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ── parse_retry_after_ms tests ────────────────────────────────────────────

    fn make_headers(pairs: &[(&str, &str)]) -> Headers {
        let mut h = Headers::new();
        for (k, v) in pairs {
            h.insert(k.to_string(), v.to_string());
        }
        h
    }

    #[test]
    fn parse_retry_after_integer_seconds_to_ms() {
        let h = make_headers(&[("retry-after", "30")]);
        assert_eq!(parse_retry_after_ms(&h), Some(30_000));
    }

    #[test]
    fn parse_retry_after_missing_returns_none() {
        let h = make_headers(&[]);
        assert_eq!(parse_retry_after_ms(&h), None);
    }

    #[test]
    fn parse_retry_after_http_date_returns_none() {
        // HTTP-date format is not supported; return None rather than panic.
        let h = make_headers(&[("retry-after", "Wed, 21 Oct 2015 07:28:00 GMT")]);
        assert_eq!(parse_retry_after_ms(&h), None);
    }

    #[test]
    fn parse_retry_after_non_numeric_returns_none() {
        let h = make_headers(&[("retry-after", "soon")]);
        assert_eq!(parse_retry_after_ms(&h), None);
    }

    // ── classify tests ────────────────────────────────────────────────────────

    #[test]
    fn throttling_maps_to_rate_limited() {
        match classify(
            Some("ThrottlingException"),
            Some(429),
            "slow down",
            Some(2000),
        ) {
            ModelError::RateLimited { retry_after_ms } => {
                assert_eq!(retry_after_ms, Some(2000));
            }
            other => panic!("expected RateLimited, got {other:?}"),
        }
    }

    #[test]
    fn throttling_without_retry_after() {
        assert!(matches!(
            classify(Some("ThrottlingException"), None, "slow", None),
            ModelError::RateLimited {
                retry_after_ms: None
            }
        ));
    }

    #[test]
    fn service_unavailable_maps_to_unavailable() {
        assert!(matches!(
            classify(Some("ServiceUnavailableException"), Some(503), "down", None),
            ModelError::Unavailable
        ));
    }

    #[test]
    fn model_not_ready_maps_to_unavailable() {
        assert!(matches!(
            classify(Some("ModelNotReadyException"), None, "not ready", None),
            ModelError::Unavailable
        ));
    }

    #[test]
    fn internal_server_exception_maps_to_unavailable() {
        assert!(matches!(
            classify(Some("InternalServerException"), Some(500), "boom", None),
            ModelError::Unavailable
        ));
    }

    #[test]
    fn model_stream_error_maps_to_unavailable() {
        assert!(matches!(
            classify(
                Some("ModelStreamErrorException"),
                None,
                "stream error",
                None
            ),
            ModelError::Unavailable
        ));
    }

    #[test]
    fn model_timeout_maps_to_unavailable() {
        assert!(matches!(
            classify(Some("ModelTimeoutException"), None, "timeout", None),
            ModelError::Unavailable
        ));
    }

    #[test]
    fn access_denied_maps_to_refused() {
        match classify(Some("AccessDeniedException"), Some(403), "no access", None) {
            ModelError::Refused { reason } => assert_eq!(reason, "no access"),
            other => panic!("expected Refused, got {other:?}"),
        }
    }

    #[test]
    fn validation_exception_too_long_maps_to_context_length() {
        assert!(matches!(
            classify(
                Some("ValidationException"),
                Some(400),
                "prompt is too long: 200k tokens",
                None
            ),
            ModelError::ContextLengthExceeded
        ));
    }

    #[test]
    fn validation_exception_maximum_context_maps_to_context_length() {
        assert!(matches!(
            classify(
                Some("ValidationException"),
                Some(400),
                "Input length exceeds maximum context length",
                None
            ),
            ModelError::ContextLengthExceeded
        ));
    }

    #[test]
    fn validation_exception_other_maps_to_other() {
        assert!(matches!(
            classify(
                Some("ValidationException"),
                Some(400),
                "missing field",
                None
            ),
            ModelError::Other(_)
        ));
    }

    #[test]
    fn unknown_code_maps_to_other() {
        assert!(matches!(
            classify(Some("UnknownFutureException"), None, "idk", None),
            ModelError::Other(_)
        ));
    }

    #[test]
    fn none_code_maps_to_other() {
        assert!(matches!(
            classify(None, None, "no code", None),
            ModelError::Other(_)
        ));
    }
}
//! [`BedrockModel`] — the Bedrock Converse API model handle.
//!
//! Wraps an `Arc<Config>` so that the model handle is `Clone + Send + Sync`
//! and the `BoxStream` returned by `invoke` can be `'static + Send`.

use std::sync::Arc;

use async_stream::stream;
use async_trait::async_trait;
use futures_core::stream::BoxStream;
use paigasus_helikon_core::{
    CancellationToken, Model, ModelCapabilities, ModelError, ModelEvent, ModelRequest,
};

use crate::builder::Config;
use crate::error::{map_sdk_error, map_sdk_http_error};
use crate::policy::ForcedChoicePolicy;
use crate::stream::StreamTranslator;
use crate::translate::build_request;

// ── BedrockModel ──────────────────────────────────────────────────────────────

/// An Amazon Bedrock Converse API model handle.
///
/// Construct via [`BedrockModel::converse`] (sync builder) or
/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
///
/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
/// Clones share the state that the handle learns at run time.
#[derive(Debug, Clone)]
pub struct BedrockModel {
    pub(crate) config: Arc<Config>,
    pub(crate) policy: Arc<ForcedChoicePolicy>,
}

// ── Model impl ────────────────────────────────────────────────────────────────

#[async_trait]
impl Model for BedrockModel {
    /// Stream model events from Amazon Bedrock's Converse API.
    ///
    /// The returned stream is `'static + Send`.
    ///
    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
    /// ends immediately without emitting a final `Finish` event (per the core
    /// `Model` trait contract).
    async fn invoke(
        &self,
        request: ModelRequest,
        cancel: CancellationToken,
    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
        // Translate the core request into Bedrock wire format (early error on
        // translation failure — before we open any network connection).
        let prepared = build_request(&self.config, &request, self.policy.path())?;
        for n in &prepared.notices {
            self.policy.note(*n, &self.config.model_id);
        }

        let synthesizing = prepared.synthesizing;
        let client = self.config.client.clone();

        // Build the fluent ConverseStream request from the prepared parts.
        let fluent = client
            .converse_stream()
            .model_id(&prepared.model_id)
            .set_messages(Some(prepared.messages))
            .set_system(if prepared.system.is_empty() {
                None
            } else {
                Some(prepared.system)
            })
            .set_tool_config(prepared.tool_config)
            .set_inference_config(prepared.inference_config)
            .set_output_config(prepared.output_config);

        let s = stream! {
            // Send the ConverseStream request and obtain the event receiver.
            // Guard with a cancellation check (biased: cancel arm wins) so that
            // a token already fired — or one that fires during the HTTP send —
            // aborts cleanly without opening a dangling Bedrock stream and
            // without emitting Finish (per the Model::invoke cancellation contract).
            let output = tokio::select! {
                biased;
                _ = cancel.cancelled() => { return; }
                result = fluent.send() => {
                    // map_sdk_http_error: fluent.send() returns
                    // SdkError<_, HttpResponse>, so we can extract Retry-After headers.
                    match result {
                        Ok(o) => o,
                        Err(e) => {
                            yield Err(map_sdk_http_error(e));
                            return;
                        }
                    }
                }
            };

            let mut receiver = output.stream;
            let mut translator = StreamTranslator::new(synthesizing);

            loop {
                let next = tokio::select! {
                    biased;
                    _ = cancel.cancelled() => {
                        // Cancellation: end stream without emitting Finish.
                        return;
                    }
                    r = receiver.recv() => r,
                };

                match next {
                    // Stream exhausted normally (EOF).
                    // Flush any buffered stop reason that arrived without a
                    // subsequent Metadata event so the consumer always sees
                    // a terminal Finish.
                    Ok(None) => {
                        if let Some(terminal) = translator.finish() {
                            yield terminal;
                        }
                        return;
                    }
                    // Good event — feed through translator and yield results.
                    Ok(Some(event)) => {
                        for result in translator.consume(event) {
                            yield result;
                        }
                    }
                    // Transport-level error on the event stream.
                    Err(e) => {
                        yield Err(map_sdk_error(e));
                        return;
                    }
                }
            }
        };

        Ok(Box::pin(s))
    }

    fn capabilities(&self) -> ModelCapabilities {
        self.config.capabilities
    }

    fn provider(&self) -> &str {
        "bedrock"
    }

    fn model(&self) -> &str {
        &self.config.model_id
    }
}

// ── Unit tests (descriptor + capability + cancellation contract) ──────────────

#[cfg(test)]
mod tests {
    use super::*;
    use aws_config::{BehaviorVersion, Region};
    use futures_core::stream::BoxStream;

    // ── Cancellation-wrapper helper (test-only) ───────────────────────────────

    /// Wrap any `Stream<Item = Result<ModelEvent, ModelError>>` with a
    /// `CancellationToken` guard.
    ///
    /// When `cancel` fires, the returned stream ends immediately **without**
    /// emitting a `Finish` event — matching the `Model::invoke` cancellation
    /// contract.
    fn drive_stream_with_token<S>(
        source: S,
        cancel: CancellationToken,
    ) -> BoxStream<'static, Result<ModelEvent, ModelError>>
    where
        S: futures_core::Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static,
    {
        Box::pin(stream! {
            tokio::pin!(source);
            loop {
                let next = tokio::select! {
                    biased;
                    _ = cancel.cancelled() => return,
                    r = futures_util::StreamExt::next(&mut source) => r,
                };
                match next {
                    None => return,
                    Some(v) => yield v,
                }
            }
        })
    }

    fn offline_model(model_id: &str) -> BedrockModel {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async {
            let sdk_cfg = aws_config::defaults(BehaviorVersion::v2026_11_17())
                .region(Region::new("us-east-1"))
                .test_credentials()
                .load()
                .await;
            BedrockModel::converse(model_id)
                .sdk_config(&sdk_cfg)
                .build()
                .expect("build offline model")
        })
    }

    #[test]
    fn clones_share_the_policy() {
        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
        let m2 = m.clone();
        assert!(m.policy.record_rejection());
        assert_eq!(m2.policy.path(), crate::policy::OutputPath::Native);
        let fresh = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
        assert_eq!(fresh.policy.path(), crate::policy::OutputPath::ForcedTool);
    }

    // `offline_model` blocks on its own runtime, so this test is a plain
    // `#[test]` that drives `invoke` on a second runtime.
    #[test]
    fn invoke_rejects_blank_only_request_before_network() {
        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
        let mut req = ModelRequest::new();
        req.messages = vec![paigasus_helikon_core::Item::UserMessage {
            content: vec![paigasus_helikon_core::ContentPart::Text {
                text: String::new(),
            }],
        }];
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        let res = rt.block_on(m.invoke(req, CancellationToken::new()));
        match res {
            Err(ModelError::Other(e)) => assert!(
                e.to_string().contains("no message with content to send"),
                "unexpected error: {e}"
            ),
            Err(e) => panic!("unexpected error variant: {e}"),
            Ok(_) => panic!("expected an error"),
        }
    }

    #[test]
    fn provider_returns_bedrock() {
        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
        assert_eq!(m.provider(), "bedrock");
    }

    #[test]
    fn model_returns_configured_id() {
        let id = "anthropic.claude-3-5-sonnet-20241022-v2:0";
        let m = offline_model(id);
        assert_eq!(m.model(), id);
    }

    #[test]
    fn capabilities_matches_caps_for_anthropic() {
        let m = offline_model("anthropic.claude-3-5-sonnet-20241022-v2:0");
        let caps = m.capabilities();
        assert!(caps.streaming);
        assert!(caps.tools);
        assert!(caps.structured_output);
        assert!(
            !caps.vision,
            "vision not advertised (no image-block mapping)"
        );
    }

    #[test]
    fn model_is_clone() {
        let m = offline_model("amazon.nova-pro-v1:0");
        let m2 = m.clone();
        assert_eq!(m.model(), m2.model());
    }

    // ── Cancellation contract tests ───────────────────────────────────────────

    use futures_core::Stream;
    use futures_util::StreamExt;

    /// Build a stream that yields `n` `TokenDelta` events then ends.
    fn token_stream(
        n: usize,
    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
            .map(|i| {
                Ok(ModelEvent::TokenDelta {
                    text: format!("chunk-{i}"),
                })
            })
            .collect();
        futures_util::stream::iter(events)
    }

    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
    fn token_stream_with_finish(
        n: usize,
    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
        use paigasus_helikon_core::FinishReason;
        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
            .map(|i| {
                Ok(ModelEvent::TokenDelta {
                    text: format!("chunk-{i}"),
                })
            })
            .collect();
        events.push(Ok(ModelEvent::Finish {
            reason: FinishReason::Stop,
        }));
        futures_util::stream::iter(events)
    }

    #[tokio::test]
    async fn cancel_before_stream_ends_no_finish() {
        let cancel = CancellationToken::new();
        let source = token_stream(10);

        // Cancel immediately — the stream should yield 0 events and no Finish.
        cancel.cancel();
        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;

        let has_finish = events
            .iter()
            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
        assert!(!has_finish, "cancelled stream must not emit Finish");
    }

    #[tokio::test]
    async fn cancel_mid_stream_no_finish() {
        use std::sync::atomic::{AtomicBool, Ordering};
        use std::sync::Arc;

        let cancel = CancellationToken::new();
        let cancel_clone = cancel.clone();

        // A stream that cancels itself after yielding the first token.
        let cancelled = Arc::new(AtomicBool::new(false));
        let cancelled_clone = cancelled.clone();

        let source = async_stream::stream! {
            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
            // Signal cancellation after the first token.
            if !cancelled_clone.swap(true, Ordering::SeqCst) {
                cancel_clone.cancel();
            }
            // `biased;` in drive_stream_with_token's tokio::select! checks the
            // cancel arm first on every iteration, so once cancel() fires the
            // driver exits before polling the source again — making this
            // single-threaded ordering deterministic and guaranteeing no Finish
            // is emitted after cancel.
            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
        };

        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;

        let has_finish = events
            .iter()
            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
        assert!(!has_finish, "mid-stream cancel must not emit Finish");
    }

    #[tokio::test]
    async fn uncancelled_stream_emits_finish() {
        let cancel = CancellationToken::new();
        let source = token_stream_with_finish(3);

        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;

        let has_finish = events
            .iter()
            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
        assert!(has_finish, "uncancelled stream must emit Finish");
        // All 3 token deltas + finish = 4 events.
        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
    }

    #[tokio::test]
    async fn cancel_does_not_drop_events_already_yielded() {
        let cancel = CancellationToken::new();
        // 5 events, no finish.  Don't cancel — all should arrive.
        let source = token_stream(5);
        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
    }
}
//! Per-handle policy for the forced tool choice and the structured-output path.

use std::sync::atomic::{AtomicBool, Ordering};

use crate::family::{rejects_forced_tool_choice, ModelFamily};

/// The wire path that carries a structured-output or forced-tool request.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum OutputPath {
    /// Use a synthetic forced tool.
    ForcedTool,
    /// Use the native structured-output field.
    Native,
}

/// A notice that the native path changes the request. Each kind is logged once per handle.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum NativeNotice {
    /// `ToolChoice::Required` is omitted.
    RequiredOmitted,
    /// `ToolChoice::Tool` is omitted.
    ToolOmitted,
    /// `ResponseFormat::JsonObject` degrades to text.
    JsonObjectAsText,
}

/// State that selects the output path for one model handle.
#[derive(Debug)]
pub(crate) struct ForcedChoicePolicy {
    rejects_static: bool,
    learned: AtomicBool,
    family: ModelFamily,
    warned: [AtomicBool; 3],
}

impl ForcedChoicePolicy {
    /// Make a policy. The static rule comes from the model id.
    pub(crate) fn new(model_id: &str, family: ModelFamily) -> Self {
        Self::with_rule(rejects_forced_tool_choice(model_id), family)
    }

    /// Make a policy with no static rule.
    #[cfg(test)]
    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
        Self::with_rule(false, family)
    }

    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
        Self {
            rejects_static,
            learned: AtomicBool::new(false),
            family,
            warned: [
                AtomicBool::new(false),
                AtomicBool::new(false),
                AtomicBool::new(false),
            ],
        }
    }

    /// The model family of this handle.
    // Used from Task 4 (build_request path selection).
    #[allow(dead_code)]
    pub(crate) fn family(&self) -> ModelFamily {
        self.family
    }

    /// The output path for the next request.
    pub(crate) fn path(&self) -> OutputPath {
        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
            OutputPath::Native
        } else {
            OutputPath::ForcedTool
        }
    }

    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
    // Used from Task 5 (send fallback).
    #[allow(dead_code)]
    pub(crate) fn record_rejection(&self) -> bool {
        !self.learned.swap(true, Ordering::SeqCst)
    }

    /// Returns `true` only the first time for each notice kind.
    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
        !self.warned[n as usize].swap(true, Ordering::SeqCst)
    }

    /// Log the notice once per handle.
    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
        if !self.first_notice(n) {
            return;
        }
        let text = match n {
            NativeNotice::RequiredOmitted => {
                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
            }
            NativeNotice::ToolOmitted => {
                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
            }
            NativeNotice::JsonObjectAsText => {
                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
            }
        };
        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
    }
}

