22	//! Map Amazon Bedrock SDK errors to [`paigasus_helikon_core::ModelError`].
23	//!
24	//! Per ADR-10 (*No silent auto-retry inside the loop*), the runner never
25	//! retries — retries are an application-layer concern via `RetryingModel`.
26	//!
27	//! The `classify` function is a pure, unit-testable classifier that operates
28	//! on string error codes and optional HTTP status codes, mirroring the style
29	//! of the Anthropic provider's `map_error_type`. `map_sdk_error` wraps it
30	//! by extracting the code/status from the real [`SdkError`] variants.
31	
32	use aws_smithy_runtime_api::client::result::SdkError;
33	use aws_smithy_runtime_api::http::Headers;
34	use aws_smithy_types::error::metadata::ProvideErrorMetadata;
35	use paigasus_helikon_core::ModelError;
36	
37	/// Classify a Bedrock error into a [`ModelError`] from raw components.
38	///
39	/// This function is intentionally pure so it can be unit-tested without
40	/// constructing live `SdkError` values.
41	///
42	/// | `code`                       | Result                             |
43	/// |------------------------------|------------------------------------|
44	/// | `ThrottlingException`        | `RateLimited { retry_after_ms }`   |
45	/// | `ServiceUnavailableException`, `ModelNotReadyException`, `InternalServerException`, `ModelStreamErrorException`, `ModelTimeoutException` | `Unavailable` |
46	/// | `AccessDeniedException`      | `Refused { reason: message }`      |
47	/// | `ValidationException` + message contains "too long"/"maximum context" | `ContextLengthExceeded` |
48	/// | `ValidationException` (other)| `Other`                            |
49	/// | unknown / `None`             | `Other`                            |
50	pub(crate) fn classify(
51	    code: Option<&str>,
52	    _status: Option<u16>,
53	    message: &str,
54	    retry_after_ms: Option<u64>,
55	) -> ModelError {
56	    match code {
57	        Some("ThrottlingException") => ModelError::RateLimited { retry_after_ms },
58	        Some(
59	            "ServiceUnavailableException"
60	            | "ModelNotReadyException"
61	            | "InternalServerException"
62	            | "ModelStreamErrorException"
63	            | "ModelTimeoutException",
64	        ) => ModelError::Unavailable,
65	        Some("AccessDeniedException") => ModelError::Refused {
66	            reason: message.to_owned(),
67	        },
68	        Some("ValidationException") => {
69	            let msg_lower = message.to_ascii_lowercase();
70	            if msg_lower.contains("too long") || msg_lower.contains("maximum context") {
71	                ModelError::ContextLengthExceeded
72	            } else {
73	                ModelError::Other(anyhow::anyhow!("bedrock ValidationException: {message}"))
74	            }
75	        }
76	        _ => ModelError::Other(anyhow::anyhow!(
77	            "bedrock error {}: {message}",
78	            code.unwrap_or("unknown")
79	        )),
80	    }
81	}
