83	/// Parse the `Retry-After` header (integer seconds) from Bedrock response headers into milliseconds.
84	///
85	/// Returns `None` when the header is absent or its value is not a non-negative integer
86	/// (HTTP-date retry-after values are not supported — `None` is the safe fallback).
87	pub(crate) fn parse_retry_after_ms(headers: &Headers) -> Option<u64> {
88	    headers
89	        .get("retry-after")
90	        .and_then(|v| v.trim().parse::<u64>().ok())
91	        .map(|seconds| seconds.saturating_mul(1000))
92	}
