94	/// Map a Bedrock SDK [`SdkError`] to a [`ModelError`].
95	///
96	/// For `ServiceError`, the modeled error code and message are extracted via
97	/// [`ProvideErrorMetadata`] and delegated to [`classify`]. Transport-level
98	/// failures (`DispatchFailure`, `TimeoutError`, `ConstructionFailure`,
99	/// `ResponseError`) map to [`ModelError::Transport`].
100	///
101	/// This generic variant does **not** inspect HTTP headers (the response type `R`
102	/// may not be an HTTP response — e.g. the event-stream `recv()` path produces
103	/// `SdkError<_, RawMessage>`). Call [`map_sdk_http_error`] when `R` is known to
104	/// be [`aws_smithy_runtime_api::http::Response`] and you want `Retry-After`
105	/// header extraction.
106	pub(crate) fn map_sdk_error<E, R>(err: SdkError<E, R>) -> ModelError
107	where
108	    E: ProvideErrorMetadata + std::fmt::Debug,
109	    R: std::fmt::Debug,
110	{
111	    match &err {
112	        SdkError::ServiceError(svc) => {
113	            let code = svc.err().code();
114	            let message = svc.err().message().unwrap_or("");
115	            classify(code, None, message, None)
116	        }
117	        SdkError::DispatchFailure(_)
118	        | SdkError::TimeoutError(_)
119	        | SdkError::ConstructionFailure(_)
120	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
121	        // Non-exhaustive: treat any future variant as transport.
122	        _ => ModelError::Transport(format!("{err:?}")),
123	    }
124	}
125	
126	/// Map a Bedrock SDK [`SdkError`] whose response type is the concrete HTTP
127	/// response to a [`ModelError`], extracting `Retry-After` header and HTTP
128	/// status from the raw response.
129	///
130	/// This is the preferred variant for the initial `fluent.send()` call on a
131	/// Bedrock operation, where the SDK returns
132	/// `SdkError<E, aws_smithy_runtime_api::client::orchestrator::HttpResponse>`.
133	pub(crate) fn map_sdk_http_error<E>(
134	    err: SdkError<E, aws_smithy_runtime_api::http::Response>,
135	) -> ModelError
136	where
137	    E: ProvideErrorMetadata + std::fmt::Debug,
138	{
139	    match &err {
140	        SdkError::ServiceError(svc) => {
141	            let code = svc.err().code();
142	            let message = svc.err().message().unwrap_or("");
143	            let raw = svc.raw();
144	            let status = Some(raw.status().as_u16());
145	            let retry_after_ms = parse_retry_after_ms(raw.headers());
146	            classify(code, status, message, retry_after_ms)
147	        }
148	        SdkError::DispatchFailure(_)
149	        | SdkError::TimeoutError(_)
150	        | SdkError::ConstructionFailure(_)
151	        | SdkError::ResponseError(_) => ModelError::Transport(format!("{err:?}")),
152	        // Non-exhaustive: treat any future variant as transport.
153	        _ => ModelError::Transport(format!("{err:?}")),
154	    }
155	}
