353	/// An Amazon Bedrock Converse API model handle.
354	///
355	/// Construct via [`BedrockModel::converse`] (sync builder) or
356	/// [`BedrockModel::from_env`] (async, loads AWS config from the environment).
357	///
358	/// The handle is `Clone + Send + Sync` because it holds only `Arc` values.
359	/// Clones share the state that the handle learns at run time.
360	#[derive(Debug, Clone)]
361	pub struct BedrockModel {
362	    pub(crate) config: Arc<Config>,
363	    pub(crate) policy: Arc<ForcedChoicePolicy>,
364	}
365	
366	// ── Model impl ────────────────────────────────────────────────────────────────
367	
368	#[async_trait]
369	impl Model for BedrockModel {
370	    /// Stream model events from Amazon Bedrock's Converse API.
371	    ///
372	    /// The returned stream is `'static + Send`.
373	    ///
374	    /// **Cancellation contract:** when `cancel` fires mid-stream, the stream
375	    /// ends immediately without emitting a final `Finish` event (per the core
376	    /// `Model` trait contract).
377	    async fn invoke(
378	        &self,
379	        request: ModelRequest,
380	        cancel: CancellationToken,
381	    ) -> Result<BoxStream<'static, Result<ModelEvent, ModelError>>, ModelError> {
382	        // Translate the core request into Bedrock wire format (early error on
383	        // translation failure — before we open any network connection).
384	        let prepared = build_request(&self.config, &request, self.policy.path())?;
385	        for n in &prepared.notices {
386	            self.policy.note(*n, &self.config.model_id);
387	        }
388	
389	        let synthesizing = prepared.synthesizing;
390	        let client = self.config.client.clone();
391	
392	        // Build the fluent ConverseStream request from the prepared parts.
393	        let fluent = client
394	            .converse_stream()
395	            .model_id(&prepared.model_id)
396	            .set_messages(Some(prepared.messages))
397	            .set_system(if prepared.system.is_empty() {
398	                None
399	            } else {
400	                Some(prepared.system)
401	            })
402	            .set_tool_config(prepared.tool_config)
403	            .set_inference_config(prepared.inference_config)
404	            .set_output_config(prepared.output_config);
405	
406	        let s = stream! {
407	            // Send the ConverseStream request and obtain the event receiver.
408	            // Guard with a cancellation check (biased: cancel arm wins) so that
409	            // a token already fired — or one that fires during the HTTP send —
410	            // aborts cleanly without opening a dangling Bedrock stream and
411	            // without emitting Finish (per the Model::invoke cancellation contract).
412	            let output = tokio::select! {
413	                biased;
414	                _ = cancel.cancelled() => { return; }
415	                result = fluent.send() => {
416	                    // map_sdk_http_error: fluent.send() returns
417	                    // SdkError<_, HttpResponse>, so we can extract Retry-After headers.
418	                    match result {
419	                        Ok(o) => o,
420	                        Err(e) => {
421	                            yield Err(map_sdk_http_error(e));
422	                            return;
423	                        }
424	                    }
425	                }
426	            };
427	
428	            let mut receiver = output.stream;
429	            let mut translator = StreamTranslator::new(synthesizing);
430	
431	            loop {
432	                let next = tokio::select! {
433	                    biased;
434	                    _ = cancel.cancelled() => {
435	                        // Cancellation: end stream without emitting Finish.
436	                        return;
437	                    }
438	                    r = receiver.recv() => r,
439	                };
440	
441	                match next {
442	                    // Stream exhausted normally (EOF).
443	                    // Flush any buffered stop reason that arrived without a
444	                    // subsequent Metadata event so the consumer always sees
445	                    // a terminal Finish.
446	                    Ok(None) => {
447	                        if let Some(terminal) = translator.finish() {
448	                            yield terminal;
449	                        }
450	                        return;
451	                    }
452	                    // Good event — feed through translator and yield results.
453	                    Ok(Some(event)) => {
454	                        for result in translator.consume(event) {
455	                            yield result;
456	                        }
457	                    }
458	                    // Transport-level error on the event stream.
459	                    Err(e) => {
460	                        yield Err(map_sdk_error(e));
461	                        return;
462	                    }
463	                }
464	            }
465	        };
466	
467	        Ok(Box::pin(s))
468	    }
