609	    // ── Cancellation contract tests ───────────────────────────────────────────
610	
611	    use futures_core::Stream;
612	    use futures_util::StreamExt;
613	
614	    /// Build a stream that yields `n` `TokenDelta` events then ends.
615	    fn token_stream(
616	        n: usize,
617	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
618	        let events: Vec<Result<ModelEvent, ModelError>> = (0..n)
619	            .map(|i| {
620	                Ok(ModelEvent::TokenDelta {
621	                    text: format!("chunk-{i}"),
622	                })
623	            })
624	            .collect();
625	        futures_util::stream::iter(events)
626	    }
627	
628	    /// Build a stream that yields `n` `TokenDelta` events then a `Finish` event.
629	    fn token_stream_with_finish(
630	        n: usize,
631	    ) -> impl Stream<Item = Result<ModelEvent, ModelError>> + Send + 'static {
632	        use paigasus_helikon_core::FinishReason;
633	        let mut events: Vec<Result<ModelEvent, ModelError>> = (0..n)
634	            .map(|i| {
635	                Ok(ModelEvent::TokenDelta {
636	                    text: format!("chunk-{i}"),
637	                })
638	            })
639	            .collect();
640	        events.push(Ok(ModelEvent::Finish {
641	            reason: FinishReason::Stop,
642	        }));
643	        futures_util::stream::iter(events)
644	    }
645	
646	    #[tokio::test]
647	    async fn cancel_before_stream_ends_no_finish() {
648	        let cancel = CancellationToken::new();
649	        let source = token_stream(10);
650	
651	        // Cancel immediately — the stream should yield 0 events and no Finish.
652	        cancel.cancel();
653	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
654	
655	        let has_finish = events
656	            .iter()
657	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
658	        assert!(!has_finish, "cancelled stream must not emit Finish");
659	    }
660	
661	    #[tokio::test]
662	    async fn cancel_mid_stream_no_finish() {
663	        use std::sync::atomic::{AtomicBool, Ordering};
664	        use std::sync::Arc;
665	
666	        let cancel = CancellationToken::new();
667	        let cancel_clone = cancel.clone();
668	
669	        // A stream that cancels itself after yielding the first token.
670	        let cancelled = Arc::new(AtomicBool::new(false));
671	        let cancelled_clone = cancelled.clone();
672	
673	        let source = async_stream::stream! {
674	            yield Ok::<ModelEvent, ModelError>(ModelEvent::TokenDelta { text: "first".to_owned() });
675	            // Signal cancellation after the first token.
676	            if !cancelled_clone.swap(true, Ordering::SeqCst) {
677	                cancel_clone.cancel();
678	            }
679	            // `biased;` in drive_stream_with_token's tokio::select! checks the
680	            // cancel arm first on every iteration, so once cancel() fires the
681	            // driver exits before polling the source again — making this
682	            // single-threaded ordering deterministic and guaranteeing no Finish
683	            // is emitted after cancel.
684	            yield Ok(ModelEvent::TokenDelta { text: "second".to_owned() });
685	            yield Ok(ModelEvent::Finish { reason: paigasus_helikon_core::FinishReason::Stop });
686	        };
687	
688	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
689	
690	        let has_finish = events
691	            .iter()
692	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
693	        assert!(!has_finish, "mid-stream cancel must not emit Finish");
694	    }
695	
696	    #[tokio::test]
697	    async fn uncancelled_stream_emits_finish() {
698	        let cancel = CancellationToken::new();
699	        let source = token_stream_with_finish(3);
700	
701	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
702	
703	        let has_finish = events
704	            .iter()
705	            .any(|r| matches!(r, Ok(ModelEvent::Finish { .. })));
706	        assert!(has_finish, "uncancelled stream must emit Finish");
707	        // All 3 token deltas + finish = 4 events.
708	        assert_eq!(events.len(), 4, "expected 3 tokens + 1 finish");
709	    }
710	
711	    #[tokio::test]
712	    async fn cancel_does_not_drop_events_already_yielded() {
713	        let cancel = CancellationToken::new();
714	        // 5 events, no finish.  Don't cancel — all should arrive.
715	        let source = token_stream(5);
716	        let events: Vec<_> = drive_stream_with_token(source, cancel).collect().await;
717	        assert_eq!(events.len(), 5, "all events must arrive when not cancelled");
718	    }
719	}
720	//! Per-handle policy for the forced tool choice and the structured-output path.
721	
722	use std::sync::atomic::{AtomicBool, Ordering};
723	
724	use crate::family::{rejects_forced_tool_choice, ModelFamily};
725	
726	/// The wire path that carries a structured-output or forced-tool request.
727	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
728	pub(crate) enum OutputPath {
729	    /// Use a synthetic forced tool.
730	    ForcedTool,
731	    /// Use the native structured-output field.
732	    Native,
733	}
734	
735	/// A notice that the native path changes the request. Each kind is logged once per handle.
736	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
737	pub(crate) enum NativeNotice {
738	    /// `ToolChoice::Required` is omitted.
739	    RequiredOmitted,
740	    /// `ToolChoice::Tool` is omitted.
741	    ToolOmitted,
742	    /// `ResponseFormat::JsonObject` degrades to text.
743	    JsonObjectAsText,
744	}
745	
746	/// State that selects the output path for one model handle.
747	#[derive(Debug)]
748	pub(crate) struct ForcedChoicePolicy {
749	    rejects_static: bool,
750	    learned: AtomicBool,
751	    family: ModelFamily,
752	    warned: [AtomicBool; 3],
753	}
754	
755	impl ForcedChoicePolicy {
756	    /// Make a policy. The static rule comes from the model id.
757	    pub(crate) fn new(model_id: &str, family: ModelFamily) -> Self {
758	        Self::with_rule(rejects_forced_tool_choice(model_id), family)
759	    }
760	
761	    /// Make a policy with no static rule.
762	    #[cfg(test)]
763	    pub(crate) fn without_static_rule(family: ModelFamily) -> Self {
764	        Self::with_rule(false, family)
765	    }
766	
767	    fn with_rule(rejects_static: bool, family: ModelFamily) -> Self {
768	        Self {
769	            rejects_static,
770	            learned: AtomicBool::new(false),
771	            family,
772	            warned: [
773	                AtomicBool::new(false),
774	                AtomicBool::new(false),
775	                AtomicBool::new(false),
776	            ],
777	        }
778	    }
779	
780	    /// The model family of this handle.
781	    // Used from Task 4 (build_request path selection).
782	    #[allow(dead_code)]
783	    pub(crate) fn family(&self) -> ModelFamily {
784	        self.family
785	    }
786	
787	    /// The output path for the next request.
788	    pub(crate) fn path(&self) -> OutputPath {
789	        if self.rejects_static || self.learned.load(Ordering::SeqCst) {
790	            OutputPath::Native
791	        } else {
792	            OutputPath::ForcedTool
793	        }
794	    }
795	
796	    /// Record that the service rejected a forced tool choice. Returns `true` only for the first call.
797	    // Used from Task 5 (send fallback).
798	    #[allow(dead_code)]
799	    pub(crate) fn record_rejection(&self) -> bool {
800	        !self.learned.swap(true, Ordering::SeqCst)
801	    }
802	
803	    /// Returns `true` only the first time for each notice kind.
804	    pub(crate) fn first_notice(&self, n: NativeNotice) -> bool {
805	        !self.warned[n as usize].swap(true, Ordering::SeqCst)
806	    }
807	
808	    /// Log the notice once per handle.
809	    pub(crate) fn note(&self, n: NativeNotice, model_id: &str) {
810	        if !self.first_notice(n) {
811	            return;
812	        }
813	        let text = match n {
814	            NativeNotice::RequiredOmitted => {
815	                "ToolChoice::Required is omitted: this model rejects a forced tool choice"
816	            }
817	            NativeNotice::ToolOmitted => {
818	                "ToolChoice::Tool is omitted: this model rejects a forced tool choice"
819	            }
820	            NativeNotice::JsonObjectAsText => {
821	                "ResponseFormat::JsonObject degrades to text: native output cannot express a free-form object"
822	            }
823	        };
824	        tracing::warn!(target: "paigasus::bedrock::translate", model_id = %model_id, "{text}");
825	    }
826	}
