836	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5-5", Anthropic).path(),
837	            OutputPath::Native
838	        );
839	        assert_eq!(
840	            ForcedChoicePolicy::new("global.anthropic.claude-sonnet-5", Anthropic).path(),
841	            OutputPath::ForcedTool
842	        );
843	        let p = ForcedChoicePolicy::without_static_rule(Anthropic);
844	        assert_eq!(p.path(), OutputPath::ForcedTool);
845	        assert!(p.record_rejection());
