847	        let both = ForcedChoicePolicy::new("us.anthropic.claude-opus-5-5", Anthropic);
848	        both.record_rejection();
849	        assert_eq!(both.path(), OutputPath::Native);
850	    }
851	
852	    #[test]
853	    fn record_rejection_is_true_only_once_across_threads() {
854	        let p = std::sync::Arc::new(ForcedChoicePolicy::without_static_rule(Anthropic));
855	        let firsts: usize = (0..8)
856	            .map(|_| {
857	                let p = p.clone();
858	                std::thread::spawn(move || p.record_rejection())
859	            })
860	            .collect::<Vec<_>>()
861	            .into_iter()
