    let second = rebuild(OutputPath::Native)?;
    for n in &second.notices {
        policy.note(*n, model_id);
    }
    let synthesizing = second.synthesizing;
    match send(second).await {
        Ok(output) => Ok(Sent {
            output,
            synthesizing,
        }),
        Err(f) => Err(f.error),
    }
